// Synthetic BiDi collector responses: no browser process or network needed.
#include "bidi_har.hpp"
#include <iostream>
#include <stdexcept>
#include <set>
using namespace suitecut;
using namespace suitecut::detail;
namespace { int checks=0,serial=0,reads=0,response_reads=0;std::set<std::string> collectors;void check(bool v,const char* m){if(!v)throw std::runtime_error(m);++checks;}}
namespace suitecut::detail {
Json BidiRuntime::call(const std::string& method,Json params,Deadline){if(method=="network.addDataCollector"){auto id="collector-"+std::to_string(++serial);collectors.insert(id);return Json{{"collector",id}};}if(method=="network.removeDataCollector"){collectors.erase(params.at("collector").as_string());return Json::object{};}if(method=="network.getData"){check(params.at("disown").as_bool(),"getData disowns data");check(collectors.contains(params.at("collector").as_string()),"owned collector");++reads;bool response=params.at("dataType").as_string()=="response";if(response)++response_reads;return Json{{"bytes",Json{{"type",response?"base64":"string"},{"value",response?"AAECAw==":"payload=hello"}}}};}throw std::runtime_error(method);}
}
Json event(std::string method,std::string id="r",int hop=0){Json timing{{"requestTime",100},{"dnsStart",101},{"dnsEnd",103},{"connectStart",103},{"tlsStart",104},{"connectEnd",108},{"requestStart",110},{"responseStart",120},{"responseEnd",125}};Json p{{"context","page"},{"timestamp",1700000000123.0},{"redirectCount",hop},{"request",Json{{"request",id},{"url","http://localhost/path?a=one&a=two"},{"method","POST"},{"headers",Json::array{Json{{"name","Content-Type"},{"value",Json{{"type","string"},{"value","text/plain"}}}}}},{"cookies",Json::array{}},{"headersSize",40},{"bodySize",13},{"timings",timing}}}};if(method!="network.beforeRequestSent")p["response"]=Json{{"status",hop?200:302},{"statusText",hop?"OK":"Found"},{"protocol","HTTP/1.1"},{"mimeType","application/octet-stream"},{"headers",Json::array{Json{{"name","Location"},{"value",Json{{"type","string"},{"value","/final"}}}}}},{"headersSize",50},{"bodySize",4},{"content",Json{{"size",4}}}};return Json{{"method",method},{"params",p}};}
int main(){try{auto start=event("network.beforeRequestSent").at("params"),finish=event("network.responseCompleted").at("params");auto converted=bidi_har_entry(start,finish,Json{{"type","string"},{"value","payload=hello"}},Json{{"type","base64"},{"value","AAECAw=="}});check(converted.at("startedDateTime").as_string()=="2023-11-14T22:13:20.123Z","epoch timestamp");check(converted.at("timings").at("ssl").as_double()==4,"SSL interval");check(converted.at("time").as_double()==25,"timings sum excludes nested SSL");check(converted.at("request").at("queryString").as_array().size()==2,"duplicate query parameters");check(converted.at("request").at("postData").at("text").as_string()=="payload=hello","POST data");check(converted.at("response").at("redirectURL").as_string()=="/final","redirect location");check(converted.at("response").at("content").at("encoding").as_string()=="base64","binary encoding");finish["errorText"]="connection refused";auto failed=bidi_har_entry(start,finish,Json(),Json(),"not retained");check(failed.at("_error").as_string()=="connection refused","failure metadata");check(failed.at("response").at("content").at("_bodyError").as_string()=="not retained","body omission explicit");
 BidiRuntime runtime;BidiPage page;page.browsing_context="page";BidiHar har;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);har.setup(runtime,page,deadline);check(collectors.empty(),"setup does not collect");har.command(runtime,page,Json{{"action","harStart"},{"content","embed"}},deadline);check(collectors.size()==1,"lazy collector");for(int hop=0;hop<2;++hop){har.observe(event("network.beforeRequestSent","r",hop),"page");har.observe(event("network.responseCompleted","r",hop),"page");}auto archive=har.command(runtime,page,Json{{"action","harStop"}},deadline);check(archive.at("log").at("entries").at(0).at("response").at("status").is_integer(),"HAR HTTP statuses use integer JSON values");check(archive.at("log").at("entries").as_array().size()==2,"redirect hops retained");check(collectors.empty(),"stop removes collector");check(reads==2,"shared redirect ID collected only at final hop");check(!archive.at("log").at("entries").at(0).at("response").at("content").contains("text"),"redirect does not steal final-hop body");check(archive.at("log").at("entries").at(1).at("response").at("content").at("text")==Json("AAECAw=="),"final redirect hop retains actual body");auto body=har.command(runtime,page,Json{{"action","body"},{"requestId","r"}},deadline);check(body.at("body").as_string()=="AAECAw=="&&body.at("base64Encoded").as_bool(),"body normalization");har.command(runtime,page,Json{{"action","harStart"}},deadline);int response_before_failure=response_reads;har.observe(event("network.beforeRequestSent","failed-post",1),"page");auto fail_event=event("network.fetchError","failed-post",1);fail_event.at("params").as_object().erase("response");fail_event["params"]["errorText"]="socket closed";har.observe(fail_event,"page");har.observe(event("network.beforeRequestSent","recovered",1),"page");har.observe(event("network.responseCompleted","recovered",1),"page");auto failure_archive=har.command(runtime,page,Json{{"action","exportHar"}},deadline).at("log").at("entries");check(failure_archive.at(0).at("_error")==Json("socket closed"),"failed POST preserves native error");check(failure_archive.at(0).at("request").at("postData").at("text")==Json("payload=hello"),"failed POST data read and disowned");check(response_reads==response_before_failure+1,"failed request only drains request data");check(failure_archive.at(1).at("response").at("content").at("text")==Json("AAECAw=="),"body collection recovers after failure");har.command(runtime,page,Json{{"action","harStart"},{"content","omit"}},deadline);check(collectors.size()==1,"omit installs request-only collector");int before=response_reads;har.observe(event("network.beforeRequestSent","omit-post",1),"page");har.observe(event("network.responseCompleted","omit-post",1),"page");auto omitted=har.command(runtime,page,Json{{"action","exportHar"}},deadline).at("log").at("entries").at(0);check(!omitted.at("response").at("content").contains("text"),"omit excludes response bodies");check(omitted.at("request").at("postData").at("text")==Json("payload=hello"),"omit retains request POST data");har.command(runtime,page,Json{{"action","harStart"},{"content","omit"}},deadline);for(int n=0;n<300;++n){har.observe(event("network.beforeRequestSent",std::to_string(n)),"page");har.observe(event("network.responseCompleted",std::to_string(n)),"page");}auto bounded=har.command(runtime,page,Json{{"action","exportHar"}},deadline);check(bounded.at("log").at("entries").as_array().size()==256,"entry ring bound");check(bounded.at("log").at("_droppedEntries").as_int()==44,"exact metadata drops");check(response_reads==before,"omit does not collect response data");har.command(runtime,page,Json{{"action","harStart"}},deadline);for(int n=0;n<130;++n)har.observe(event("network.beforeRequestSent",std::to_string(n)),"page");while(har.drain(runtime,deadline)){}check(collectors.empty(),"outstanding collector limit retires remote collector");try{har.command(runtime,page,Json{{"action","body"},{"requestId","unknown"}},deadline);}catch(const std::exception&){}check(collectors.size()==1,"explicit body restarts retired collector");har.observe(event("network.beforeRequestSent","after-retire",1),"page");har.observe(event("network.responseCompleted","after-retire",1),"page");auto resumed=har.command(runtime,page,Json{{"action","body"},{"requestId","after-retire"}},deadline);check(resumed.at("body")==Json("AAECAw=="),"restarted collector resumes bounded draining");har.cleanup(runtime,deadline);har.forget("page");std::cout<<"PASS "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
